select * from {{ ref('timeline__transport_index') }}

),

registry as (
    select source, clock from {{ ref('ripple_time_registry') }}
)

select
    u.ripple_source,
    case
        when u.ripple_clock = 'planned'
             and u.ripple_day <= current_date()
            then coalesce(r.clock, u.ripple_clock)
        when u.ripple_clock in ('happened', 'reported', 'decided')
             and u.ripple_day > current_date()
            then 'planned'
        else u.ripple_clock
    end as ripple_clock,
    u.ripple_grain,
    u.ripple_day,
    u.n_rows
from unioned u
left join registry r on r.source = u.ripple_source
